-- ===== rules (tools/atlas_rules.luau, appended by gen_atlas.py) =====
-- state.Atlas = { Nodes = { [id] = true } }   state.MapsDone = maps finished   state.UniquesDone = { [uniqueId] = true }
-- POINTS: 1 per map tier you've beaten in time (RiftBest, up to 30) + 1 per 10 maps finished (the first 20 points, 200
-- maps) then 1 per 30 more maps (up to 16 more, 680 maps) + 1 per Unique map you've cleared in time (4): 70 at most for
-- ~110 nodes, so a tree is a choice. (0.66 pacing: the old 20-point cap was reached ~25 h after maps open at ~18 h,
-- far short of the ~200 h to level 400.) REFUND: REFUND_COST Prism a node.
AtlasData.MAX_TIER_POINTS = 30
AtlasData.MAX_MAP_POINTS = 36
AtlasData.MAPS_PER_POINT = 10
AtlasData.LATE_MAPS, AtlasData.LATE_MAPS_PER_POINT = 200, 30 -- (after the first 200 maps: a point every 30)
function AtlasData.MapPoints(mapsDone: any): number
    local m = math.floor(tonumber(mapsDone) or 0)
    local early = math.min(AtlasData.LATE_MAPS, m) // AtlasData.MAPS_PER_POINT
    local late = math.max(0, m - AtlasData.LATE_MAPS) // AtlasData.LATE_MAPS_PER_POINT
    return math.min(AtlasData.MAX_MAP_POINTS, early + late)
end
AtlasData.REFUND_COST = 2 -- Prism
AtlasData.START = "A_START"

local function Owned(state: any): { [string]: boolean }
    local a = type(state) == "table" and type(state.Atlas) == "table" and state.Atlas.Nodes
    return type(a) == "table" and a or {}
end
AtlasData.Owned = Owned

-- (MAPS V2 L2, 2026-10-30; owner: "just do whatever POE does" -- the tree is never all yours, choices matter) POINTS =
-- 1 per map tier beaten in time (RiftBest, up to MAX_TIER_POINTS) + 1 per COMPLETIONS_PER_POINT completions (MapCompletion: each
-- map type beaten in time on each band) + 1 per MAPS_PER_POINT_V2 maps finished (up to MAX_MAP_POINTS_V2). At the launch cap:
-- 12 + 92 / 2 + 10 = 68 points for 113 nodes (~60%); a mid player (all Ruin + Dread completions, best tier 8, ~100 maps) ~36.
-- Nobody loses points: the total is the higher of this and the old formula (LegacyPoints, max 52 at launch).
AtlasData.COMPLETIONS_PER_POINT = 2
AtlasData.MAPS_PER_POINT_V2, AtlasData.MAX_MAP_POINTS_V2 = 20, 10
function AtlasData.LegacyPoints(state: any): number
    if type(state) ~= "table" then return 0 end
    local u = 0
    for _ in pairs(type(state.UniquesDone) == "table" and state.UniquesDone or {}) do u += 1 end
    return math.min(AtlasData.MAX_TIER_POINTS, math.floor(tonumber(state.RiftBest) or 0))
        + AtlasData.MapPoints(state.MapsDone) + u
end
function AtlasData.Breakdown(state: any): { [string]: number }
    local MC = require(script.Parent:WaitForChild("MapCompletion"))
    local st = type(state) == "table" and state or {}
    local done = MC.Count(st)
    local b = {
        Tier = math.min(AtlasData.MAX_TIER_POINTS, math.max(0, math.floor(tonumber(st.RiftBest) or 0))),
        CompDone = done, CompTotal = MC.Total(), Completion = done // AtlasData.COMPLETIONS_PER_POINT,
        Maps = math.min(AtlasData.MAX_MAP_POINTS_V2, math.max(0, math.floor(tonumber(st.MapsDone) or 0)) // AtlasData.MAPS_PER_POINT_V2),
        Legacy = AtlasData.LegacyPoints(st),
    }
    b.New = b.Tier + b.Completion + b.Maps
    b.Total = math.max(b.New, b.Legacy)
    return b
end
function AtlasData.PointsFor(state: any): number
    if type(state) ~= "table" then return 0 end
    return AtlasData.Breakdown(state).Total
end
function AtlasData.Spent(state: any): number
    local n = 0
    for id in pairs(Owned(state)) do if AtlasData.Nodes[id] and id ~= AtlasData.START then n += 1 end end
    return n
end
function AtlasData.Free(state: any): number
    return AtlasData.PointsFor(state) - AtlasData.Spent(state)
end

-- every allocated node's stats summed, keystone flags set (Stats.K_COLLECTOR = true ...)
function AtlasData.Stats(state: any): { [string]: any }
    local s = {}
    for id in pairs(Owned(state)) do
        local n = AtlasData.Nodes[id]
        if n then
            for k, v in pairs(n.Stats) do s[k] = (s[k] or 0) + v end
            if n.Key then s[n.Key] = true end
        end
    end
    return s
end

-- map crafting cost in Prism after the tree (Artisan smalls / Steady Hands, Master Artisan = free)
function AtlasData.CraftCost(state: any, base: number): number
    local A = AtlasData.Stats(state)
    if A.K_ARTISAN then return 0 end
    return math.max(1, math.ceil(base * (1 - math.min(0.6, A.CraftDiscount or 0))))
end

local function Linked(owned: { [string]: boolean }, id: string): boolean
    for _, l in ipairs(AtlasData.Nodes[id].Links) do
        if l == AtlasData.START or owned[l] then return true end
    end
    return false
end
function AtlasData.CanAllocate(state: any, id: string): (boolean, string?)
    local n = AtlasData.Nodes[id]
    if not n or id == AtlasData.START then return false, "Unknown node." end
    local owned = Owned(state)
    if owned[id] then return false, "Already taken." end
    if AtlasData.Free(state) <= 0 then return false, "No map points left. Clear higher tiers in time, beat map types in time (COMPLETION) and finish maps for more." end
    if not Linked(owned, id) then return false, "Take a node next to it first." end
    return true
end
-- a refund must leave every other taken node connected to the start
function AtlasData.CanRefund(state: any, id: string): (boolean, string?)
    local owned = Owned(state)
    if not owned[id] then return false, "Not taken." end
    local rest = {}
    for k in pairs(owned) do if k ~= id and AtlasData.Nodes[k] then rest[k] = true end end
    local seen, queue = { [AtlasData.START] = true }, { AtlasData.START }
    while #queue > 0 do
        local cur = table.remove(queue)
        for _, l in ipairs(AtlasData.Nodes[cur].Links) do
            if rest[l] and not seen[l] then seen[l] = true; table.insert(queue, l) end
        end
    end
    for k in pairs(rest) do
        if not seen[k] then return false, "Other nodes depend on it: refund the outer ones first." end
    end
    return true
end

return AtlasData

